using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
[InitializeOnLoad]public static class SunkenUnderpassAudit{
static SunkenUnderpassAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("SunkenUnderpassAudit.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("SunkenUnderpassAudit.request");Run();}
class R{public MeshFilter f;public Bounds b;public bool x;public float width,len;public Vector3[] p;public int[] ids;}
static T V<T>(object o,string n){return(T)o.GetType().GetField(n).GetValue(o);}static bool Height(R r,Vector3 p,out float y){var a=new object[]{r.p,r.ids,p,0f};var ok=(bool)typeof(FinalPathwayRepair).GetMethod("Height",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,a);y=(float)a[3];return ok;}
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var roads=new List<R>();foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var r=f.GetComponent<Renderer>();if(!f.sharedMesh||!r||!r.sharedMaterials.Any(m=>m&&m.name=="Road Atlas"))continue;var d=typeof(FinalPathwayRepair).GetMethod("Read",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{f.sharedMesh});var b=r.bounds;roads.Add(new R{f=f,b=b,x=b.size.x>b.size.z,width=Mathf.Min(b.size.x,b.size.z),len=Mathf.Max(b.size.x,b.size.z),p=V<Vector3[]>(d,"p").Select(f.transform.TransformPoint).ToArray(),ids=V<int[]>(d,"ids")});}
foreach(var road in roads.Where(r=>r.b.size.y<.12f))log.AppendLine("ROAD "+road.f.name+" len="+road.len+" width="+road.width+" bounds="+road.b);foreach(var low in roads.Where(r=>r.len>180&&r.width>24&&r.width<32&&r.b.size.y<.12f))foreach(var upper in roads.Where(r=>r.x!=low.x&&r.width>24&&r.width<34&&r.b.size.y<.12f)){var p=low.x?new Vector3(upper.b.center.x,low.b.center.y,low.b.center.z):new Vector3(low.b.center.x,low.b.center.y,upper.b.center.z);float margin=low.x?Mathf.Min(p.x-low.b.min.x,low.b.max.x-p.x):Mathf.Min(p.z-low.b.min.z,low.b.max.z-p.z);if(margin<95||!Height(low,p,out float y)||!Height(upper,p,out float u)||Mathf.Abs(u-y)>.2f)continue;log.AppendLine("ATGRADE lower="+low.f.name+" upper="+upper.f.name+" at="+p+" margin="+margin+" lowbounds="+low.b+" upperbounds="+upper.b);}
foreach(var a in roads.Where(r=>r.len>95&&r.width>26&&r.width<34&&r.b.size.y<.12f))foreach(var b in roads.Where(r=>r.len>95&&r.width>26&&r.width<34&&r.b.size.y<.12f&&r.x==a.x&&string.CompareOrdinal(r.f.name,a.f.name)>0)){
float lateral=a.x?Mathf.Abs(a.b.center.z-b.b.center.z):Mathf.Abs(a.b.center.x-b.b.center.x);if(lateral>4.5f)continue;var left=(a.x?a.b.center.x<b.b.center.x:a.b.center.z<b.b.center.z)?a:b;var right=left==a?b:a;float edgeA=a.x?left.b.max.x:left.b.max.z,edgeB=a.x?right.b.min.x:right.b.min.z,gap=edgeB-edgeA;if(gap<20||gap>46)continue;var p=a.x?new Vector3((edgeA+edgeB)/2,a.b.center.y,(a.b.center.z+b.b.center.z)/2):new Vector3((a.b.center.x+b.b.center.x)/2,a.b.center.y,(edgeA+edgeB)/2);var junction=roads.FirstOrDefault(r=>r.len<55&&r.width>20&&Height(r,p,out float h)&&Mathf.Abs(h-p.y)<.2f);if(junction==null)continue;var orth=roads.Where(r=>r.x!=a.x&&r.len>70&&r.b.size.y<.12f&&r.b.SqrDistance(p)<600).ToArray();if(orth.Length<1)continue;log.AppendLine("JUNCTION left="+left.f.name+" right="+right.f.name+" junction="+junction.f.name+" x="+a.x+" center="+p+" lengths="+left.len+","+right.len+" upper="+string.Join(",",orth.Select(r=>r.f.name)));}
foreach(var low in roads.Where(r=>r.len>120&&r.width>24&&r.width<32&&r.b.size.y<.12f))foreach(var upper in roads.Where(r=>r.b.size.y>8)){foreach(var anchor in new[]{new Vector3(168.47f,27.67f,418.27f),new Vector3(-62.9f,27.67f,339.01f)})if(Height(low,anchor,out float y)&&Height(upper,anchor,out float u)&&u-y>8)log.AppendLine("OLD lower="+low.f.name+" upper="+upper.f.name+" at="+anchor+" upperY="+u+" bounds="+low.b);}
}catch(Exception e){log.AppendLine("FAILED "+e);}File.WriteAllText("FinalEnvironmentRoadReview/SunkenAudit.txt",log.ToString());}}



